SELECT SUM(order_amount) AS order_amount
FROM fact_order
WHERE date_id >= 20250101 AND date_id < 20250201;

SELECT COUNT(CASE WHEN c.gender = '男' THEN f.order_id END) / COUNT(f.order_id) AS male_order_ratio
FROM fact_order f
LEFT JOIN dim_customer c ON f.customer_id = c.customer_id;

SELECT CONCAT(ROUND(SUM(CASE WHEN dc.member_level = '黄金' THEN fo.order_amount ELSE 0 END) / NULLIF(SUM(fo.order_amount), 0) * 100, 2), '%') AS gold_member_consumption_ratio
FROM fact_order fo
LEFT JOIN dim_customer dc ON fo.customer_id = dc.customer_id;
